// CSD_RATIONALE_BEGIN
// SQL-generation CSD for the spider dataset.
// The strategy emits "SQL: " as free unconstrained tokens, then opens a
// constrained span with "<<" and generates the SQL query body under full
// parser control. The parser enforces valid SQL syntax token-by-token.
// We use AdaptiveConstrainedStep with group boosting from validTokenGroups
// (which carry schema-relevant tokens) to prefer schema-grounded tokens
// while the parser's branch factor is narrow. Once the span is complete
// we close it with CloseConstrainedSpan, emitting ">>".
// State tracked:
//   - steps: token budget consumed
//   - insideConstrainedOut / currentConstrainedOut: parser-span state
//   - generated: full visible output including delimiters
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Outside-span branch: implication is vacuous; we only flip
//   insideConstrainedOut to true when next == "<<", setting
//   currentConstrainedOut := [] which is valid by parser.IsValidPrefix([])
//   (from precondition).
//   Inside-span, complete branch: CloseConstrainedSpan sets insideConstrainedOut
//   := false, making the implication vacuously true; currentConstrainedOut is
//   cleared to [].
//   Inside-span, incomplete branch: AdaptiveConstrainedStep returns either EOS
//   (we break) or a parser-valid next token; AppendConstrainedToken extends
//   currentConstrainedOut by that token, preserving parser.IsValidPrefix.
// progress:
//   Outside branch: one UnconstrainedStep consumes 1 step and appends at most
//   one token (or zero on EOS), so |generated| <= |generatedPrefix| + steps.
//   Complete branch: CloseConstrainedSpan appends ">>" (1 token) and costs 1
//   step, preserving the bound.
//   Incomplete branch: AdaptiveConstrainedStep costs 1 step; AppendConstrainedToken
//   appends 1 token on non-EOS, so visible growth matches step growth.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly one SQL query in the form: SQL: <<YOUR QUERY>>. Use only the schema provided. No explanation, no markdown.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 16;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for the spider dataset.
// Root cause of prior failure: the strategy was watching for a "<<" token from
// UnconstrainedStep, but the model was almost never emitting "<<" freely.
// Only 1/300 examples had a visible "<<", meaning the constrained span was
// almost never opened. The model generated garbage ("S!!!", "!!!...") in
// unconstrained mode instead of SQL.
//
// Fix: Use GenerateWithPrefixAndManagedSpan which hard-caps the unconstrained
// preamble (prefixBudget = 8 tokens for "SQL: ") then forces open a constrained
// span for the SQL query body. This guarantees the span is opened and parser
// control is applied.
//
// The guidance is updated to be more directive about the exact output format.
// We use a small prefixBudget (8) to allow the model to emit "SQL: " naturally,
// then force the constrained span open. Inside the span, AdaptiveConstrainedStep
// with validTokenGroups provides schema-grounded token preferences.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   GenerateWithPrefixAndManagedSpan discharges all parser-validity obligations
//   internally. Its postcondition guarantees:
//   !insideConstrainedOut ==> currentConstrainedOut == []
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   So the invariant is established at call return without additional proof work.
// progress:
//   GenerateWithPrefixAndManagedSpan costs at most +maxSteps token-steps and
//   appends at most maxSteps tokens, so |generated| <= |generatedPrefix| + maxSteps.
//   We set cost := maxSteps conservatively (the helper may use fewer steps but
//   we are allowed cost <= maxSteps). The progress postcondition
//   (maxSteps == 0 || cost > 0 || ...) is satisfied because maxSteps > 0
//   implies cost = maxSteps > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly one line: SQL: <<SELECT ...>>. Write only the SQL query inside the angle brackets. Use the schema tables and columns exactly as given. No explanation, no markdown, no extra text.";
helpers.AppendTaskGuidance(lm, guidance);

var prefixBudget: nat := 8;
if prefixBudget > maxSteps {
  prefixBudget := maxSteps;
}

var boostAmount: real := 4.0;
var narrowThreshold: nat := 16;

var gOut, iOut, cOut := helpers.GenerateWithPrefixAndManagedSpan(
  lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
  maxSteps, prefixBudget, validTokenGroups, boostAmount, narrowThreshold, eosToken
);

generated := gOut;
insideConstrainedOut := iOut;
currentConstrainedOut := cOut;

cost := maxSteps;

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for spider dataset.
//
// Diagnosis of prior failures:
// 1. "Examples with visible `<<`: 0/300" - the constrained span was opened
//    internally but the visible << was never emitted. GenerateWithPrefixAndManagedSpan
//    uses hidden constrained chunks, not visible << >> delimiters. But the task
//    requires visible << >> (Contains << >>: required).
// 2. The model was generating partial SQL then "!!!!!..." garbage, indicating
//    it ran out of valid constrained tokens and the span wasn't being properly
//    parser-controlled throughout.
// 3. "No-complete-span wrong answers: 232/300" - the span was never completed
//    (CloseConstrainedSpan was called only 122 times but never produced a
//    complete visible span).
//
// Root fix: Use an explicit approach that:
//   a) Emits "SQL: " as unconstrained prefix (at most 4 steps)
//   b) Explicitly opens a constrained span with OpenConstrainedSpan (emits "<<")
//   c) Runs AdaptiveConstrainedStep inside the span for SQL tokens
//   d) Closes with CloseSpanWithinBudget which handles the ">>" emission
//
// The key insight: we must call OpenConstrainedSpan explicitly to get visible "<<"
// rather than relying on the model to emit it naturally.
//
// We use a tight guidance string and directly control the span lifecycle.
// The SQL parser is trusted to produce syntactically valid SQL within the span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. At initialization, insideConstrainedOut = insideConstrained and
//      currentConstrainedOut = currentConstrained, which satisfies the precondition.
//   2. In Phase 1 (unconstrained prefix): we only set insideConstrainedOut = true
//      via OpenConstrainedSpan, which sets currentConstrainedOut = [] (valid empty prefix).
//   3. After OpenConstrainedSpan, we are in the constrained loop.
//      AdaptiveConstrainedStep returns EOS or a parser-valid next token.
//      AppendConstrainedToken preserves parser validity.
//      CloseSpanWithinBudget's postcondition guarantees:
//        insideOut ==> parser.IsValidPrefix(currentOut)
//        !insideOut ==> currentOut == []
//      So parser_validity is maintained throughout.
//
// progress:
//   Phase 1: Each unconstrained step increments steps by 1 and appends at most
//     1 token to generated. OpenConstrainedSpan increments steps by 1 and
//     appends "<<" (1 token). So |generated| <= |generatedPrefix| + steps.
//   Phase 2 (constrained loop): Each AdaptiveConstrainedStep increments steps
//     by 1 and AppendConstrainedToken appends 1 token. So the bound holds.
//   CloseSpanWithinBudget: uses closeBudget = maxSteps - steps steps and appends
//     at most closeBudget tokens, so final |generated| <= |generatedPrefix| + maxSteps.
//   cost := steps <= maxSteps satisfies cost <= maxSteps.
//   Progress postcondition: if maxSteps > 0, Phase 1 takes at least 1 step
//     (the OpenConstrainedSpan call), so cost > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Complete the task by outputting: SQL: <<your SQL query here>>. The SQL query must be inside << and >>. Use only the tables and columns from the provided schema.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Generate unconstrained prefix "SQL: " (up to 6 steps)
// Stop as soon as we have enough prefix or hit EOS
var prefixDone: bool := false;
while steps < maxSteps && steps < 6 && !insideConstrainedOut && !prefixDone
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    prefixDone := true;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
      prefixDone := true;
    }
  }
}

// Phase 2: If not already in a constrained span, force open one
if !insideConstrainedOut && steps < maxSteps && !prefixDone {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate constrained SQL tokens inside the span
while steps < maxSteps && insideConstrainedOut && steps + 2 <= maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    // Reserve at least 1 step for closing
    if steps + 1 <= maxSteps {
      var closeBudget: nat := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    }
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, 16, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If still inside span, use CloseSpanWithinBudget with remaining budget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for spider dataset.
//
// Diagnosis of attempt 3 failure: "Examples with visible <<: 0/300"
// The AdaptiveConstrainedStep helper was called but "AdaptiveConstrainedStep"
// is NOT in the allowed helper list for this attempt. The call failed silently
// or caused fallback to garbage output. The visible << was never emitted
// because OpenConstrainedSpan was called but the constrained loop used an
// invalid helper.
//
// Diagnosis of best attempt (attempt 2): accuracy 22.7%, syntax 40.7%
// GenerateWithPrefixAndManagedSpan was used and DID work (constrained activity
// in 300/300 examples), but produced 0 visible "<<" tokens (hidden span mode).
// The evaluator requires visible << >> delimiters. The answer extraction was
// failing because the span was hidden, not visible.
//
// Root fix strategy:
// Use an explicit loop with OpenConstrainedSpan (to emit visible "<<"),
// then ConstrainedStep/AdaptiveConstrainedStepWithPenalties inside the span,
// then CloseSpanWithinBudget to emit ">>".
//
// Key insight from the allowed helper list:
// - AdaptiveConstrainedStepWithPenalties IS in the allowed list
// - OpenConstrainedSpan IS in the allowed list
// - CloseSpanWithinBudget IS in the allowed list
//
// Strategy:
// 1. Emit "SQL: " as unconstrained prefix (up to 8 steps), watch for EOS
// 2. Call OpenConstrainedSpan to force visible "<<"
// 3. Generate SQL tokens with AdaptiveConstrainedStepWithPenalties
//    (schema-grounded via validTokenGroups, with "!!!" penalty)
// 4. When parser complete or budget low, call CloseSpanWithinBudget
//
// This should produce visible << >> spans with valid SQL inside.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. Initialization: insideConstrainedOut = insideConstrained,
//      currentConstrainedOut = currentConstrained, satisfying preconditions.
//   2. Phase 1 (unconstrained prefix): insideConstrainedOut is only set to true
//      via OpenConstrainedSpan (which sets currentConstrainedOut := [] - valid),
//      or when next == "<<" from UnconstrainedStep (also sets currentConstrainedOut := []).
//      While !insideConstrainedOut, the implication is vacuously true.
//   3. Phase 2 (OpenConstrainedSpan): postcondition guarantees insideConstrainedOut = true
//      and currentConstrainedOut = [] which satisfies parser.IsValidPrefix([]).
//   4. Phase 3 (constrained loop): AdaptiveConstrainedStepWithPenalties returns
//      EOS or a parser-valid next token. AppendConstrainedToken preserves
//      parser.IsValidPrefix(currentConstrainedOut).
//   5. Phase 4 (CloseSpanWithinBudget): postcondition guarantees
//      insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//      and !insideConstrainedOut ==> currentConstrainedOut == [].
//
// progress:
//   Phase 1: Each step increments steps by 1, appends at most 1 token.
//     |generated| <= |generatedPrefix| + steps maintained.
//   Phase 2 (OpenConstrainedSpan): steps += 1, appends "<<" (1 token). Bound holds.
//   Phase 3: Each AdaptiveConstrainedStepWithPenalties step increments steps by 1,
//     AppendConstrainedToken appends 1 token. Bound holds.
//   Phase 4 (CloseSpanWithinBudget): closeBudget = maxSteps - steps.
//     Postcondition: |generatedOut| <= |generated| + closeBudget <= |generatedPrefix| + maxSteps.
//     We set steps := maxSteps after the call.
//   cost := steps <= maxSteps satisfies cost <= maxSteps.
//   Progress postcondition: maxSteps > 0 implies Phase 1 takes at least 1 step
//     (OpenConstrainedSpan), so cost >= 1 > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly: SQL: <<your SQL query>>. The SQL query goes inside << and >>. Use only tables and columns from the schema. Write valid SQL only.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Generate unconstrained prefix "SQL: " (up to 8 steps)
// Watch for natural "<<" emission or EOS
var prefixSteps: nat := 8;
if prefixSteps > maxSteps {
  prefixSteps := maxSteps;
}

while steps < prefixSteps && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    // EOS during prefix - stop
    cost := steps;
    return;
  } else {
    generated := generated + [next];
    if next == "<<" {
      // Model naturally opened a span
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: If not yet in a constrained span, force open one with visible "<<"
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Build penalty tokens - tokens we want to avoid (common garbage tokens)
var penaltyTokens: seq<Token> := ["!", "!!!", "!!!!"];

// Phase 3: Generate SQL tokens inside the constrained span
// Reserve 2 steps for CloseSpanWithinBudget
while steps + 2 < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Check if we've reached a complete parse - try to close
  if parser.IsCompletePrefix(currentConstrainedOut) {
    break;
  }

  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.AdaptiveConstrainedStepWithPenalties(
    lm, parser, constrainedPrompt, currentConstrainedOut,
    validTokenGroups, 4.0, penaltyTokens, 4.0, 12, eosToken
  );
  steps := steps + 1;

  if next == eosToken {
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Close the span if still open, using remaining budget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for spider dataset - attempt 5.
//
// Root cause analysis of attempt 4 failure (2.0% accuracy, 3.3% syntax):
// - "AdaptiveConstrainedStepWithPenalties" was NOT in the allowed helper list
//   for that attempt, causing the constrained loop to generate garbage ("S!!!", "!!!...")
// - The penalty tokens ["!", "!!!", "!!!!"] caused the model to generate these
//   exact tokens in unconstrained mode before the span was opened
// - "Examples with visible <<: 0/300" means OpenConstrainedSpan was either not
//   reached or its output was not being processed correctly
//
// Root cause of attempts 3-4: invalid helper "AdaptiveConstrainedStepWithPenalties"
// caused the constrained generation to malfunction.
//
// Best result was attempt 2 (22.7% accuracy) using GenerateWithPrefixAndManagedSpan,
// but 0 visible "<<" tokens (span_usefulness showed hidden/internal activity only).
//
// Key insight from diagnostics:
// - Attempt 2: "valid_nonfinal_spans_only 300/300" - spans were generated but
//   the LAST span was not the final answer. The evaluator needs the FINAL span
//   to contain the SQL.
// - "answer_source=text_fallback" in attempt 4 - the evaluator fell back to text
//   extraction, meaning no valid span was found as the answer
// - The model seems to be generating SQL in the first span (preamble?) rather
//   than the last span
//
// New strategy:
// 1. Use short unconstrained prefix (just 2-3 tokens to get "SQL: ")
// 2. Immediately force open constrained span with OpenConstrainedSpan
// 3. Use ConstrainedStep (hard parser control) inside the span
// 4. Use CloseSpanWithinBudget with sufficient budget to close cleanly
//
// The key difference from attempt 2 is using OpenConstrainedSpan explicitly
// rather than GenerateWithPrefixAndManagedSpan, to ensure the FINAL and ONLY
// span contains the SQL query.
//
// Guidance is revised to emphasize the format more strongly.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. Initialization: insideConstrainedOut = insideConstrained,
//      currentConstrainedOut = currentConstrained from preconditions.
//   2. Phase 1 (unconstrained prefix, max 3 steps): UnconstrainedStep returns
//      tokens without parser control. We only set insideConstrainedOut = true
//      if next == "<<" (natural delimiter), setting currentConstrainedOut = []
//      which satisfies parser.IsValidPrefix([]) by precondition.
//      While !insideConstrainedOut, the invariant is vacuously true.
//   3. Phase 2 (OpenConstrainedSpan): postcondition guarantees insideConstrainedOut
//      = true and currentConstrainedOut = [], satisfying parser.IsValidPrefix([]).
//   4. Phase 3 (constrained loop): ConstrainedStep returns either eosToken or a
//      parser-valid next token (by its postcondition). AppendConstrainedToken
//      then preserves parser.IsValidPrefix(currentConstrainedOut).
//      CloseSpanIfComplete either closes the span (making implication vacuous with
//      currentConstrainedOut = []) or leaves the state unchanged (still valid).
//   5. Phase 4 (CloseSpanWithinBudget): its postcondition guarantees:
//      insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//      !insideConstrainedOut ==> currentConstrainedOut == []
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: Each UnconstrainedStep increments steps by 1, appends at most 1 token.
//   Phase 2 (OpenConstrainedSpan): costs 1 step, appends "<<" (1 token). Bound holds.
//   Phase 3: ConstrainedStep costs 1 step, AppendConstrainedToken appends 1 token.
//     CloseSpanIfComplete costs 1 step and appends at most 1 token (">>").
//     Each iteration: steps += 1, |generated| increases by at most 1. Bound holds.
//   Phase 4 (CloseSpanWithinBudget with closeBudget = maxSteps - steps):
//     postcondition: |generatedOut| <= |generated| + closeBudget
//     = |generated| + (maxSteps - steps) <= |generatedPrefix| + steps + maxSteps - steps
//     = |generatedPrefix| + maxSteps. We set steps := maxSteps. Bound holds.
//   cost = steps <= maxSteps satisfies cost <= maxSteps.
//   Progress postcondition: if maxSteps > 0, Phase 2 runs (OpenConstrainedSpan),
//     so steps >= 1 >= 1 = cost > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Generate exactly: SQL: <<SQL query here>>. The SQL query must be inside << and >>. Output nothing else.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Short unconstrained prefix to get "SQL: " (at most 3 steps)
var prefixBudget: nat := 3;
if prefixBudget > maxSteps {
  prefixBudget := maxSteps;
}

while steps < prefixBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    cost := steps;
    return;
  }
  generated := generated + [next];
  if next == "<<" {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// Phase 2: Force open constrained span with visible "<<" if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL tokens inside the constrained span with hard parser control
// Reserve sufficient budget for CloseSpanWithinBudget (at least 50 steps)
var reserveForClose: nat := 50;

while steps + reserveForClose < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Try to close if complete
  var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  steps := steps + 1;
  if closed {
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
